class ios_base::failure : public std::exception {
    // Inherits from std::exception, providing virtual what() for error messages
    explicit failure(const std::string& message, const std::error_code& ec = std::io_errc::stream);
    // Implementation note: The constructor initializes the base std::exception with the message,
    // and stores the std::error_code, which is a pair of an error value and a category pointer.
    // The std::error_code's category is a polymorphic object, involving vtable lookups at runtime.
};
